var EXTRA=[{dot:"gray",j:"Sports Health",h:"Come i fisioterapisti affrontano la paura dei pazienti dopo il LCA",v:"Un'indagine qualitativa su fisioterapisti esperti esplora come riconoscono e affrontano la paura del movimento nei pazienti in riabilitazione dopo ricostruzione del LCA — un tema più discusso in ambulatorio che nella letteratura chirurgica.",pmid:'42781749',doi:'10.1177/19417381261471381',temi:["riabilitazione","psicologia dello sport"]},{dot:"gray",j:"Frontiers in Bioengineering and Biotechnology",h:"Un cambio di direzione a 45° non anticipato stressa di più il ginocchio",v:"Uno studio di biomeccanica sportiva isola l'angolo di cambio di direzione non anticipato come il gesto che più altera il carico sul ginocchio legato al rischio di lesione del LCA — dato di laboratorio, non ancora clinico.",pmid:'42780666',doi:'10.3389/fbioe.2026.1895455',temi:["biomeccanica","prevenzione LCA"]},{dot:"gray",j:"JB & JS Open Access",h:"Un farmaco per l'osteoporosi aumenta la densità ossea del femore dopo la protesi",v:"Uno studio clinico segnala che l'abaloparatide, farmaco per l'osteoporosi, aumenta la densità minerale ossea del femore distale dopo protesi totale di ginocchio — un possibile alleato nella fissazione a lungo termine, non ancora legato a un esito di sopravvivenza dell'impianto.",pmid:'42781663',doi:'10.2106/JBJS.OA.26.00176',temi:["protesi totale","farmacologia ossea"]},{dot:"gray",j:"Acta Orthopaedica",h:"Quando si torna a guidare dopo una protesi con percorso rapido",v:"Una coorte danese su pazienti con percorso di recupero rapido dopo protesi d'anca o ginocchio descrive i tempi di ripresa della guida — un'informazione pratica più che clinica, utile per il colloquio prima della dimissione.",pmid:'42781971',doi:'10.2340/17453674.2026.46649',temi:["protesi totale","recupero funzionale"]},{dot:"gray",j:"Journal of Functional Morphology and Kinesiology",h:"Quale carico di esercizio funziona meglio nella tendinopatia rotulea",v:"Una meta-analisi su pochi confronti diretti fra protocolli di carico per la tendinopatia rotulea trova un piccolo vantaggio medio per il primo protocollo elencato in ciascun confronto, con certezza dell'evidenza giudicata bassa dagli stessi autori.",pmid:'42783641',doi:'10.3390/jfmk11030348',temi:["tendinopatia rotulea","riabilitazione"]},{dot:"gray",j:"Muscles",h:"Rinforzo dell'anca o del ginocchio nella sindrome femoro-rotulea: pari efficacia",v:"Una revisione sistematica su quindici trial randomizzati trova che programmi di rinforzo dell'anca e del ginocchio migliorano entrambi dolore e funzione nella sindrome da dolore femoro-rotuleo, senza un vincitore chiaro fra i due approcci.",pmid:'42784051',doi:'10.3390/muscles5030066',temi:["dolore femoro-rotuleo","riabilitazione"]},{dot:"gray",j:"Sports (Basel)",h:"L'asimmetria di forza del tronco si associa al rischio di infortunio al ginocchio",v:"In un gruppo di calciatrici svedesi di livello elite, l'asimmetria nella forza flessoria laterale del tronco e nel test del salto laterale si associa in modo indipendente al successivo infortunio traumatico del ginocchio — risultati dichiarati esplorativi dagli stessi autori.",pmid:'42784406',doi:'10.3390/sports14090410',temi:["prevenzione infortuni","calcio femminile"]},{dot:"gray",j:"JMIR Aging",h:"La rigidità del tendine rotuleo aiuta a prevedere l'artrosi futura",v:"In anziani senza dolore al ginocchio, la rigidità del tendine rotuleo e la forza estensoria predicono in modo indipendente la comparsa di artrosi clinica nei due anni successivi — un possibile bersaglio di screening preventivo, ancora da confermare su coorti più ampie.",pmid:'42784800',doi:'10.2196/84494',temi:["artrosi","prevenzione"]},{dot:"gray",j:"Anaesthesia, Critical Care & Pain Medicine",h:"L'anestesia spinale dà un recupero migliore nei primi giorni dopo la protesi",v:"Uno studio retrospettivo francese trova un punteggio di qualità del recupero più alto al terzo giorno dopo protesi totale con anestesia spinale rispetto alla generale, senza differenze nella durata del ricovero o nella mortalità.",pmid:'42785708',doi:'10.1016/j.accpm.2026.101905',temi:["protesi totale","anestesia"]},{dot:"gray",j:"Journal of Applied Biomechanics",h:"A due anni dal LCA il ginocchio operato salta ancora in difetto",v:"In un gruppo di pazienti a circa due anni dalla ricostruzione del LCA, il ginocchio operato mostra ancora un momento estensorio e una potenza articolare ridotti nel salto, legati a un deficit persistente di forza del quadricipite più che a un problema di coordinazione.",pmid:'42785721',doi:'10.1123/jab.2026-0134',temi:["rientro allo sport","forza del quadricipite"]},{dot:"gray",j:"Journal of Functional Morphology and Kinesiology",h:"Le scarpe minimaliste per prevenire l'artrosi: l'evidenza è più debole del previsto",v:"Una revisione sistematica scopre che gli studi sulle calzature minimaliste come prevenzione dell'artrosi di ginocchio condividono in gran parte le stesse poche coorti, senza dichiararlo: i dati indipendenti restano troppo pochi per una raccomandazione, in un senso o nell'altro.",pmid:'42783666',doi:'10.3390/jfmk11030372',temi:["artrosi","prevenzione"]},{dot:"gray",j:"Journal of Pain Research",h:"L'ablazione a radiofrequenza per il dolore artrosico tiene nel tempo",v:"Una casistica retrospettiva su oltre mille ginocchia trattate con ablazione a radiofrequenza raffreddata per il dolore da artrosi riporta una buona sopravvivenza dell'effetto prima di dover ripetere la procedura — trattamento conservativo, non chirurgico, utile da conoscere per i pazienti non ancora candidati alla protesi.",pmid:'42781084',doi:'10.2147/JPR.S638862',temi:["artrosi","terapia conservativa"]}];
var SCOPERTE=[{t:"L'intelligenza artificiale sa segmentare la cartilagine del ginocchio, ma non ancora prevedere",v:"Una revisione sistematica e meta-analisi di 57 studi trova che i modelli di intelligenza artificiale segmentano la cartilagine del ginocchio su risonanza con accuratezza tecnica alta (coefficiente di Dice pooled 0,86-0,88 secondo il compartimento), ma solo tre esperimenti in tutta la letteratura hanno una validazione esterna indipendente, e l'evidenza su quanto questi modelli predicano davvero il decorso clinico resta scarsa e poco riproducibile. Vale la deviazione perché è il tuo stesso interesse per l'intelligenza artificiale applicata alla medicina, letto con lo stesso scetticismo metodologico che applichi a un trial clinico.",pmid:'42782519',doi:'10.1007/s00264-026-07032-6',temi:["intelligenza artificiale","imaging cartilagineo"]},{t:"In Cina si testa l'agopuntura insieme a un antinfiammatorio per l'artrosi di ginocchio",v:"Un protocollo di trial randomizzato controllato, registrato e già in arruolamento in tre ospedali dell'Hunan, confronterà terapia integrativa con agopuntura, celecoxib e la loro combinazione in 282 pazienti con artrosi di ginocchio: nessun risultato ancora disponibile, solo il disegno dello studio. Vale la deviazione perché mostra come la medicina tradizionale cinese venga oggi messa alla prova con gli stessi strumenti — randomizzazione, registrazione, intenzione di trattare — della medicina occidentale, un mondo che dichiari di non conoscere.",pmid:'42785936',doi:'10.1136/bmjopen-2026-124004',temi:["mondo orientale","medicina integrativa"]},{t:"A Tianjin si studia come la cartilagine danneggiata lascia entrare le molecole più grandi",v:"Un gruppo di ingegneria di Tianjin mostra, su modelli di laboratorio, che danneggiare lo strato più superficiale della cartilagine (per via enzimatica o meccanica) fa perdere alla cartilagine la sua capacità di filtrare le molecole per dimensione, lasciando penetrare più in profondità anche quelle grandi. Vale la deviazione perché è un tassello di bioingegneria di base dietro una domanda molto pratica — perché certe infiltrazioni funzionano meglio in alcuni ginocchi che in altri — vista dalla scuola cinese che la sta studiando.",pmid:'42785526',doi:'10.1016/j.ijpharm.2026.127461',temi:["bioingegneria","infiltrazioni articolari"]}];
var SOC={"1": {"video": "Al Mayo Clinic hanno confrontato due modi di riparare una radice del menisco quando si ricostruisce il legamento crociato anteriore: uno è quello che usi tu, l'altro è più recente. Su cinquanta pazienti contro cento, le percentuali di reintervento sono simili, ma chi ha avuto la tecnica più recente si dichiara un po' più soddisfatto su dolore e funzione. Il punto onesto: chi ha ricevuto la tecnica più recente è stato seguito per molto meno tempo — un anno e mezzo contro sei — quindi il confronto vero arriverà solo fra qualche anno.", "linkedin": "Coorte propensity-matched, Mayo Clinic (Arthroscopy, set 2026): fissazione con ancora intratunnel (n=50) vs riparazione transtibiale pull-through (n=100) nella radice meniscale. Reintervento 8% vs 14% (p=0,43), fallimento 4% vs 6% (p>0,99) — non significativi. PASS più frequente con l'ancora su VAS-attività (74% vs 56%, p=0,03) e Lysholm (66% vs 47%, p=0,01). Limite maggiore: follow-up 1,5 vs 6,1 anni, gruppi non contemporanei.", "instagram": "🦵 Una radice del menisco lesionata durante l'intervento al legamento crociato: due tecniche di riparazione a confronto in uno studio del Mayo Clinic. Le percentuali di nuovo intervento sono simili, chi ha avuto la tecnica più recente si dice un po' più soddisfatto — ma è stato seguito per molto meno tempo, quindi il confronto reale è ancora aperto.", "pazienti": "Quando si ricostruisce il legamento centrale del ginocchio, a volte va riparato anche un punto di aggancio del menisco chiamato radice. Uno studio americano ha confrontato due modi di farlo: i risultati a breve termine sono simili, con qualche punto in più di soddisfazione per la tecnica più nuova. È presto per dire quale sia davvero migliore, perché chi ha avuto la tecnica nuova è stato seguito per molto meno tempo."}};
var SOCV={"1": {"video": {"chir": ["Uno studio della Mayo Clinic, pubblicato su Arthroscopy, confronta due tecniche di fissazione per la riparazione della radice meniscale: la fissazione con ancora intratunnel, più recente, e la riparazione transtibiale pull-through — quella che tu esegui — su un totale di 150 ginocchia appaiate per propensione.", "Il tasso di reintervento è simile: 8% con l'ancora contro 14% con la transtibiale, differenza non significativa. Ma su due misure di soddisfazione soggettiva — il dolore in attività e il punteggio di Lysholm — una quota più alta di pazienti con l'ancora raggiunge la soglia di stato sintomatico accettabile.", "Il limite che conta di più: il gruppo con l'ancora è stato seguito in media un anno e mezzo, quello con la transtibiale sei anni. Non è un confronto alla pari nel tempo, e la tua tecnica non ha ancora un motivo solido per essere messa in discussione — ma non è più l'unica con dati recenti a favore."], "misto": ["Uno studio americano ha confrontato due modi di riparare una radice del menisco lesionata durante la ricostruzione del legamento crociato anteriore: un punto di fissazione con un'ancora dentro il tunnel osseo, più recente, e la tecnica che passa un filo attraverso la tibia (transtibiale), più consolidata.", "Le percentuali di chi ha dovuto essere rioperato sono risultate simili fra le due tecniche. Su quanto i pazienti si sono dichiarati soddisfatti per dolore e funzione, però, chi ha avuto la tecnica più recente ha risposto un po' meglio.", "Il punto onesto: chi ha avuto la tecnica più recente è stato seguito per molto meno tempo — circa un anno e mezzo, contro sei anni per l'altra tecnica. È presto per dire che una tecnica sia davvero migliore dell'altra."], "pazienti": ["A volte, quando si ricostruisce il legamento centrale del ginocchio, va riparato anche un piccolo punto di aggancio del menisco chiamato radice. Uno studio americano ha confrontato due modi di ripararlo.", "I risultati a breve termine sono simili tra le due tecniche: la percentuale di chi ha dovuto essere rioperato è quasi la stessa. Chi ha avuto la tecnica più recente si è detto un po' più soddisfatto per il dolore e per come si muove il ginocchio.", "Nota onesta: chi ha avuto la tecnica più nuova è stato seguito per meno tempo degli altri, quindi non si può ancora dire con certezza quale delle due tenga meglio negli anni."]}, "reel": {"chir": ["[Mayo Clinic, 150 ginocchia] Ancora intratunnel vs transtibiale pull-through nella riparazione della radice meniscale.", "[Il numero] Reintervento 8% vs 14% (n.s.); PASS più alto con l'ancora su VAS-attività e Lysholm.", "[Il limite] Follow-up 1,5 vs 6,1 anni — gruppi non contemporanei, confronto ancora indiretto."], "misto": ["[Due modi di riparare una radice del menisco] Un'ancora nel tunnel osseo contro il filo passato attraverso la tibia.", "[Il risultato] Percentuali di reintervento simili, soddisfazione un po' più alta con la tecnica nuova.", "[Il limite onesto] La tecnica nuova è seguita da molto meno tempo — il confronto vero arriva più avanti."], "pazienti": ["[Riparare una radice del menisco] Due tecniche diverse, stesso obiettivo.", "[La buona notizia] I risultati a breve termine sono simili, con qualche soddisfazione in più per la tecnica recente.", "[La notizia onesta] Serve più tempo di osservazione prima di sapere quale tenga meglio."]}, "linkedin": {"chir": ["Coorte propensity-matched, Mayo Clinic (Arthroscopy, set 2026), 150 riparazioni della radice meniscale: fissazione con ancora intratunnel (n=50) vs transtibiale pull-through (n=100).", "Reintervento 8% vs 14% (p=0,43) e fallimento 4% vs 6% (p>0,99): non significativi. PASS raggiunto più spesso con l'ancora su VAS-attività (74% vs 56%, p=0,03) e Lysholm (66% vs 47%, p=0,01).", "Limite maggiore: follow-up medio 1,5 anni (ancora) contro 6,1 anni (transtibiale) — gruppi non contemporanei, non una dimostrazione di superiorità."], "misto": ["Un centro americano ha confrontato due tecniche per riparare una radice del menisco lesionata insieme al legamento crociato anteriore: un'ancora nel tunnel osseo, più recente, e il passaggio del filo attraverso la tibia, più diffuso.", "I reinterventi sono risultati simili nei due gruppi. Sulla soddisfazione riferita dai pazienti per dolore e funzione, la tecnica più recente ha fatto leggermente meglio.", "Il limite da ricordare: chi ha avuto la tecnica nuova è stato seguito per molto meno tempo — un anno e mezzo contro sei anni — quindi il confronto non è ancora alla pari."], "pazienti": ["Quando si opera il legamento centrale del ginocchio, a volte va riparato anche un punto di aggancio del menisco.", "Un confronto fra due tecniche di riparazione mostra risultati simili a breve termine, con qualche soddisfazione in più per la tecnica più recente.", "Detto con onestà: la tecnica nuova è stata seguita per meno tempo, quindi la certezza su quale sia davvero migliore arriverà più avanti."]}, "instagram": {"chir": ["📊 150 ginocchia, Mayo Clinic: ancora intratunnel vs transtibiale pull-through nella radice meniscale.", "🎯 Reintervento 8% vs 14% (n.s.); PASS più alto con l'ancora su dolore e Lysholm.", "⚠️ Follow-up 1,5 vs 6,1 anni: il confronto resta indiretto."], "misto": ["🦵 Riparare una radice del menisco: due tecniche a confronto in uno studio americano.", "📈 Risultati simili sui reinterventi, un po' più di soddisfazione con la tecnica recente.", "🔍 Ma la tecnica recente è seguita da meno tempo: il confronto vero è ancora da fare."], "pazienti": ["🦵 A volte, insieme al legamento del ginocchio, va riparato anche un pezzetto del menisco.", "✅ Due modi di farlo, risultati simili a breve termine.", "📚 Serve più tempo per sapere quale tenga meglio negli anni."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #ChirurgiaDelGinocchio #Artroscopia", "instagram": "#ortopedia #menisco #radicemeniscale #chirurgiadelginocchio #legamentocrociatoanteriore #medicinasportiva #traumatologia #arthroscopy #ricercaortopedica", "kw": "riparazione radice meniscale, menisco, legamento crociato anteriore"}};
var NLB={"1": {"prof": ["Radice meniscale: l'ancora intratunnel eguaglia la transtibiale sui reinterventi, la supera sulla soddisfazione", "Una coorte propensity-matched del Mayo Clinic (50 contro 100 pazienti) confronta la fissazione con ancora intratunnel con la riparazione transtibiale pull-through della radice meniscale: reintervento e fallimento della riparazione simili, ma una quota più alta di pazienti con l'ancora raggiunge la soglia di soddisfazione soggettiva su dolore in attività e punteggio di Lysholm.", "Nota critica: il follow-up medio del gruppo con l'ancora (1,5 anni) è quattro volte più corto di quello del gruppo transtibiale (6,1 anni) — i due gruppi non sono contemporanei, e il confronto sulla durata dell'effetto resta da fare."], "mix": ["Radice meniscale: l'ancora intratunnel eguaglia la transtibiale sui reinterventi, la supera sulla soddisfazione", "Uno studio americano ha confrontato due tecniche per riparare una radice del menisco lesionata insieme al legamento crociato anteriore: un'ancora dentro il tunnel osseo, più recente, e il passaggio del filo attraverso la tibia, più diffuso. Le percentuali di reintervento sono risultate simili; sulla soddisfazione per dolore e funzione, la tecnica più recente ha fatto leggermente meglio.", "Nota sul limite: chi ha avuto la tecnica più recente è stato seguito per molto meno tempo — un anno e mezzo contro sei anni — quindi il confronto non è ancora alla pari."], "paz": ["Riparare una radice del menisco: due tecniche a confronto", "Quando si opera il legamento centrale del ginocchio, a volte va riparato anche un punto di aggancio del menisco chiamato radice. Uno studio americano ha confrontato due modi di farlo: i risultati a breve termine sono simili, con qualche soddisfazione in più riferita dai pazienti operati con la tecnica più recente.", "Nota rassicurante: entrambe le tecniche danno buoni risultati nelle mani di un chirurgo esperto; la tecnica più recente ha semplicemente meno anni di osservazione alle spalle, non un problema dimostrato."]}, "2": {"prof": ["Nell'osteotomia tibiale, una placca mediale aggiuntiva riduce il ritardo di guarigione", "Una coorte giapponese di 154 ginocchia con osteotomia tibiale alta a V invertita mostra che l'aggiunta di una piccola placca a stabilità angolare mediale, insieme alla placca laterale convenzionale, accorcia il tempo di consolidazione (8 contro 12 settimane) e riduce il ritardo di unione (2,4% contro 20,8%) e la non-unione (0% contro 5,6%), senza aumentare le complicanze.", "Nota critica: studio retrospettivo, non randomizzato, su una variante tecnica di osteotomia (V invertita) diversa dalle tecniche di correzione dello slope più comuni in Europa; la scelta della placca aggiuntiva potrebbe riflettere una selezione dei casi non descritta."], "mix": ["Nell'osteotomia tibiale, una placca mediale aggiuntiva riduce il ritardo di guarigione", "In un gruppo giapponese di 154 ginocchia operate con una tecnica di correzione dell'asse della tibia, aggiungere una piccola placca di rinforzo sul lato interno dell'osso, oltre a quella principale, ha accorciato il tempo di guarigione e ridotto nettamente i casi di guarigione ritardata o mancata, senza più complicazioni.", "Nota sul limite: lo studio non è randomizzato, e riguarda una variante tecnica specifica di osteotomia — il principio (più punti di fissazione, guarigione più rapida) resta comunque utile da conoscere."], "paz": ["Un piccolo rinforzo in più nell'osteotomia del ginocchio aiuta l'osso a guarire prima", "In un gruppo di pazienti giapponesi operati con una tecnica che corregge l'asse della tibia, aggiungere una piccola placca di sostegno oltre a quella principale ha ridotto i tempi di guarigione dell'osso e i casi in cui la guarigione tardava o non arrivava, senza aumentare le complicazioni.", "Nota rassicurante: è un accorgimento tecnico in più a disposizione del chirurgo, non un cambiamento della procedura nel suo complesso."]}, "3": {"prof": ["Nella protesi di ginocchio, il taglio della rotula orienta il rischio di complicanze", "Una coorte retrospettiva su 303 protesi robot-assistite con rivestimento rotuleo cementless mostra che un taglio della rotula a inclinazione mediale dà un'inclinazione postoperatoria più alta e la quota maggiore di linee radiotrasparenti (5,2%) rispetto a un taglio simmetrico o laterale, con una soglia di inclinazione a 7,8° predittiva.", "Nota critica: piattaforma robotica diversa dalla tua VELYS, follow-up minimo di soli 6 mesi, nessun dato su BMI e comorbidità nel modello multivariabile."], "mix": ["Nella protesi di ginocchio, il taglio della rotula orienta il rischio di complicanze", "Uno studio italiano su oltre trecento protesi di ginocchio robot-assistite mostra che il modo in cui si taglia la rotula durante l'intervento influenza quanto la rotula stessa risulterà inclinata dopo l'operazione, e che un'inclinazione troppo alta si associa a più segni radiografici di allentamento attorno alla componente.", "Nota sul limite: lo studio usa un robot diverso da quello con cui tu operi, e segue i pazienti per soli sei mesi — troppo poco per parlare di durata della protesi nel tempo."], "paz": ["Come si taglia la rotula durante la protesi di ginocchio fa la differenza", "Uno studio italiano su oltre trecento protesi di ginocchio mostra che un piccolo dettaglio tecnico — come viene tagliato l'osso della rotula durante l'intervento — influenza quanto bene la rotula resterà allineata dopo l'operazione.", "Nota rassicurante: è un controllo che un chirurgo attento può fare durante lo stesso intervento, senza bisogno di altri esami o di un intervento diverso."]}, "4": {"prof": ["La protesi parziale del compartimento laterale si rivede più spesso della protesi totale", "Il registro nazionale olandese, 847 protesi compartimentali laterali contro 240.047 protesi totali, mostra un rischio di revisione significativamente più alto per la protesi laterale (hazard ratio corretto 2,15; confermato a 1,55 nel sottogruppo 2014-2021 con aggiustamento più completo).", "Nota critica: la protesi laterale è rara anche in un registro nazionale su quindici anni, e l'indicazione clinica a sceglierla — spesso casi più complessi — può non essere del tutto controllata dal solo aggiustamento per propensione; non riguarda il compartimento mediale, molto più frequente nella pratica corrente."], "mix": ["La protesi parziale del compartimento laterale si rivede più spesso della protesi totale", "Un grande registro olandese mostra che la protesi di ginocchio limitata al lato esterno dell'articolazione (compartimento laterale) — una scelta rara — viene rivista più spesso della protesi totale, anche dopo aver tenuto conto delle differenze fra i pazienti operati con l'una o con l'altra.", "Nota sul limite: riguarda il compartimento laterale, non quello mediale che è la sede più comune della protesi parziale; è un segnale utile soprattutto per i rari casi in cui il compartimento esterno è quello danneggiato."], "paz": ["La protesi parziale su un solo lato del ginocchio: un dato da conoscere", "Un ampio registro nei Paesi Bassi mostra che, quando la protesi copre solo il lato esterno del ginocchio (una situazione meno comune), il rischio di dover rioperare è più alto rispetto alla protesi che copre tutta l'articolazione.", "Nota rassicurante: riguarda una situazione rara; nella maggior parte dei casi la protesi parziale si esegue sul lato interno del ginocchio, non toccato da questo studio."]}, "5": {"prof": ["Nella ricostruzione del collaterale mediale, un doppio fascio si avvicina di più alla stabilità nativa", "Uno studio cadaverico su 27 ginocchia mostra che una ricostruzione del legamento collaterale mediale superficiale a doppio fascio, inlay/onlay retensionabile, restituisce una lassità in valgo ed extrarotazione più vicina al ginocchio nativo rispetto a una tecnica a singolo fascio.", "Nota critica: dato di banco, non clinico; allograft di tibiale anteriore, non la tecnica con ancore FiberTak che usi tu — la superiorità biomeccanica non implica automaticamente un esito clinico migliore."], "mix": ["Nella ricostruzione del collaterale mediale, un doppio fascio si avvicina di più alla stabilità nativa", "Uno studio di laboratorio su ginocchia cadaveriche mostra che ricostruire il legamento sul lato interno del ginocchio con due fasci di tendine, invece di uno solo, restituisce una stabilità più simile a quella del ginocchio mai operato.", "Nota sul limite: è un esperimento su cadaveri, non su pazienti veri, e usa un tendine da donatore diverso dalla tecnica che si usa più spesso nella pratica clinica — un principio tecnico interessante, non ancora una prova clinica."], "paz": ["Ricostruire il legamento interno del ginocchio: due tecniche, in laboratorio", "Uno studio di laboratorio su ginocchia non di pazienti veri mostra che usare due fasci di tendine, invece di uno, per ricostruire il legamento sul lato interno del ginocchio si avvicina di più a come si comporta un ginocchio mai operato.", "Nota rassicurante: è ancora un esperimento di laboratorio, non uno studio su pazienti — serve altra ricerca prima che questo cambi la pratica clinica quotidiana."]}, "6": {"prof": ["Dopo il LCA, l'età conta anche nella biologia del ginocchio, non solo nella meccanica", "Una coorte prospettica di 100 pazienti seguiti almeno 5 anni mostra che l'età al momento della ricostruzione del LCA modula quali biomarcatori del liquido sinoviale preoperatorio predicono l'esito riferito dal paziente a lungo termine, con età più avanzata associata a punteggi peggiori e a minore probabilità di beneficio clinico rilevante.", "Nota critica: 100 pazienti suddivisi poi per fasce d'età e per singolo biomarcatore — i sottogruppi diventano piccoli, e lo studio è di associazione, non di meccanismo causale."], "mix": ["Dopo il LCA, l'età conta anche nella biologia del ginocchio, non solo nella meccanica", "Uno studio americano che ha seguito 100 pazienti per almeno 5 anni dopo la ricostruzione del legamento crociato anteriore mostra che l'età al momento dell'intervento è legata a differenze nella risposta infiammatoria del ginocchio, e che i pazienti più anziani tendono ad avere un recupero funzionale meno completo nel lungo periodo.", "Nota sul limite: lo studio mostra un'associazione, non dimostra che la biologia da sola spieghi la differenza — altri fattori legati all'età possono contribuire."], "paz": ["Perché l'età conta anche dopo l'intervento al legamento del ginocchio", "Uno studio che ha seguito 100 pazienti per almeno cinque anni dopo l'operazione al legamento crociato anteriore mostra che l'età al momento dell'intervento è legata a come il ginocchio reagisce nei mesi successivi, e che i pazienti più anziani in media recuperano un po' meno completamente nel lungo periodo.", "Nota rassicurante: sono differenze medie su un gruppo di pazienti, non una previsione per il singolo caso — l'età è uno dei tanti fattori che il chirurgo considera nel colloquio prima dell'intervento."]}, "7": {"prof": ["Nella ricostruzione del LCA, il rapporto fra innesto e impronta nativa non predice il fallimento", "Una coorte retrospettiva singaporiana di 240 ricostruzioni del LCA con autoinnesto di hamstring non trova un'associazione fra il rapporto tra area dell'innesto e impronta tibiale nativa e il fallimento precoce, su soli 7 eventi in tutta la coorte.", "Nota critica: solo 7 fallimenti in totale rendono il risultato «non significativo» uno studio muto più che una prova di assenza di effetto; innesto di hamstring, non il tendine quadricipitale/retto femorale che usi tu."], "mix": ["Nella ricostruzione del LCA, il rapporto fra innesto e impronta nativa non predice il fallimento", "Uno studio di Singapore su 240 pazienti operati di legamento crociato anteriore con innesto di hamstring non trova un legame fra quanto l'innesto ricalca la forma naturale dell'attacco del legamento e il rischio di un nuovo cedimento nei primi anni.", "Nota sul limite: i cedimenti osservati nello studio sono stati pochissimi — troppo pochi per dire con certezza che questo dettaglio tecnico non conti affatto."], "paz": ["Le dimensioni dell'innesto nel legamento crociato: un dettaglio tecnico ancora incerto", "Uno studio su 240 pazienti operati di legamento crociato anteriore a Singapore non trova un legame chiaro fra le dimensioni esatte dell'innesto usato e il rischio di doverlo rioperare nei primi anni.", "Nota rassicurante: i casi di nuovo cedimento nello studio sono stati molto pochi, un segno che comunque il rischio complessivo resta basso."]}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"orange",sec:"res",j:"Arthroscopy",h:"L'ancora intratunnel supera la tua tecnica su alcuni punteggi, non sulle rotture",v:"Coorte propensity-matched, Mayo Clinic, 50 contro 100 riparazioni della radice meniscale: fissazione con ancora intratunnel contro la tua transtibiale pull-through, reintervento 8% contro 14% (non significativo), ma più pazienti raggiungono la soglia di soddisfazione soggettiva con l'ancora.",ax:"Tagliero, Ahmad, Mikula, Hevesi, Smith, Krych",date:"set 2026",meta:"coorte retrospettiva propensity-matched, Mayo Clinic, 50 contro 100 ginocchia · [III]",pmid:'42782213',doi:'10.1002/arj.70601',journal:"Arthroscopy",authors:"Tagliero AJ, Ahmad RA, Mikula JD, Hevesi M, Smith P, Krych AJ",design:"Studio di coorte retrospettivo monocentrico (Mayo Clinic, Minnesota) su pazienti sottoposti a riparazione primaria della radice meniscale (mediale o laterale) fra il 2011 e il 2024, con confronto fra fissazione con ancora intratunnel e riparazione transtibiale pull-through — la tua tecnica; appaiamento per propensione su età, sesso, BMI, lato operato, lateralità della radice e procedure concomitanti; follow-up minimo 12 mesi.",pop:"50 pazienti con fissazione intratunnel (età media 44 anni) appaiati per propensione a 100 pazienti con riparazione transtibiale pull-through (età media 41 anni); follow-up medio 1,5 anni (range 1,0-2,3) nel gruppo ancora, 6,1 anni (range 2,7-13,7) nel gruppo transtibiale.",results:"Reintervento nell'8% (ancora) contro il 14% (transtibiale) (p=0,43); fallimento della riparazione 4% contro 6% (p>0,99). Punteggio Tegner pre e postoperatorio simile fra i gruppi, ma il 26,5% del gruppo ancora raggiunge la differenza minima clinicamente importante sul Tegner contro lo 0% del gruppo transtibiale. VAS con attività più basso nel gruppo ancora (1,8 contro 2,5; p=0,02). Lysholm postoperatorio 87 contro 83 (p=0,05), IKDC 79 contro 76 (p=0,09). Stato sintomatico accettabile (PASS) raggiunto più spesso nel gruppo ancora su VAS-attività (74% contro 56%; p=0,03) e su Lysholm (66% contro 47%; p=0,01).",concl:"Gli autori concludono che entrambe le tecniche danno alta soddisfazione e esiti clinici complessivamente comparabili a breve termine, senza differenze nei tassi di reintervento.",limits:"Il follow-up medio del gruppo ancora (1,5 anni) è più di quattro volte più corto di quello del gruppo transtibiale (6,1 anni): i due gruppi non sono contemporanei, e la tecnica più recente ha per definizione meno tempo per manifestare un fallimento tardivo · numerosità del gruppo ancora piccola (50 pazienti) per un confronto su un esito raro come il reintervento (vedi MUTE) · nessun dato radiografico di guarigione della radice in nessuno dei due gruppi.",perte:"La transtibiale pull-through è la tua tecnica di riferimento per la radice meniscale. Qui non perde su reintervento o fallimento della riparazione, ma su due misure di soddisfazione soggettiva (PASS su dolore in attività e su Lysholm) la fissazione con ancora intratunnel fa meglio — con un follow-up però quattro volte più corto, il confronto più onesto oggi è indiretto, non un motivo per cambiare tecnica. Il dato da tenere: la tua tecnica non è chiusa da questo studio, ma non è più l'unica con dati di esito a breve termine paragonabili."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Experimental Orthopaedics",h:"Una placca mediale aggiuntiva quasi azzera il ritardo di guarigione nell'osteotomia",v:"Coorte giapponese di 154 ginocchia con osteotomia tibiale alta a V invertita: la fissazione aggiuntiva con placca mediale riduce il tempo di consolidazione (8 contro 12 settimane) e il ritardo di unione (2,4% contro 20,8%), senza più complicanze.",ax:"Kaibara, Yasuda, Kondo, Yabuuchi, Inoue, Iwasaki, Yagi",date:"set 2026",meta:"coorte retrospettiva comparativa, 154 ginocchia, Giappone · [III]",pmid:'42781361',doi:'10.1002/jeo2.70919',journal:"Journal of Experimental Orthopaedics",authors:"Kaibara T, Yasuda K, Kondo E, Yabuuchi K, Inoue M, Iwasaki N, Yagi T",design:"Studio di coorte retrospettivo monocentrico (Sapporo, Giappone) su pazienti sottoposti a osteotomia tibiale alta a V invertita (iVHTO): confronto fra fissazione convenzionale con placca a compressione laterale (LCP) singola e fissazione aggiuntiva con una piccola placca a stabilità angolare mediale a T; valutazione radiografica e clinica con follow-up minimo di 2 anni.",pop:"154 ginocchia (135 pazienti): 72 nel gruppo con sola LCP, 82 nel gruppo con placca mediale aggiuntiva.",results:"Tempo alla consolidazione più breve nel gruppo con placca aggiuntiva (mediana 8 contro 12 settimane; p<0,001; IC 95% della differenza 0,0-4,0 settimane). Ritardo di unione 2,4% contro 20,8% (p<0,001; IC 95% 8,6%-29,3%), non-unione 0% contro 5,6% (p=0,046; IC 95% 0,0%-13,4%). Altre complicanze simili fra i gruppi (4,9% contro 4,2%; p=0,98). Lysholm lievemente più alto con la placca aggiuntiva (p=0,043; IC 95% 0,0-5,0), nessuna differenza sugli altri punteggi clinici.",concl:"Gli autori concludono che la fissazione aggiuntiva con placca mediale migliora la guarigione ossea e riduce il ritardo di unione dopo osteotomia a V invertita, senza aumentare le complicanze né compromettere l'esito clinico.",limits:"Studio retrospettivo, non randomizzato: la scelta della placca aggiuntiva può riflettere una selezione dei casi più complessi o più recenti, non descritta nell'abstract · monocentrico, un solo gruppo chirurgico giapponese · tecnica di osteotomia (a V invertita) diversa dalle tecniche di correzione dello slope più comuni in Europa.",perte:"Tu esegui osteotomie correttive, comprese quelle di slope: questo lavoro riguarda una variante tecnica specifica (V invertita), non necessariamente la tua, ma il principio — un secondo punto di fissazione mediale accelera la consolidazione e riduce il ritardo di unione senza costi in complicanze — è trasferibile alla discussione generale sulla stabilità della sintesi in osteotomia tibiale alta."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Orthopaedics & Traumatology: Surgery & Research",h:"Nella protesi di ginocchio un taglio rotuleo mediale inclina di più la rotula",v:"303 protesi robotiche con rivestimento rotuleo cementless: un taglio rotuleo a inclinazione mediale dà un'inclinazione postoperatoria della rotula più alta e la quota più alta di linee radiotrasparenti (5,2%) rispetto a un taglio simmetrico o laterale.",ax:"Pungitore, Meissner, Sangaletti, Vasiliadis, Theus-Steinmann, Calliess, Leggieri, Innocenti",date:"set 2026",meta:"coorte retrospettiva monocentrica, 303 protesi robot-assistite, Italia · [III]",pmid:'42785427',doi:'10.1016/j.otsr.2026.104904',journal:"Orthopaedics & Traumatology: Surgery & Research",authors:"Pungitore M, Meissner N, Sangaletti R, Vasiliadis AV, Theus-Steinmann C, Calliess T, Leggieri F, Innocenti M",design:"Studio di coorte retrospettivo su 303 protesi totali di ginocchio primarie robot-assistite con rivestimento rotuleo cementless asimmetrico (2022-2024): valutazione radiografica del piano di resezione rotulea coronale (rapporto di resezione medio-laterale) e della sua relazione con l'angolo di inclinazione rotulea postoperatoria e con la comparsa di linee radiotrasparenti attorno alla componente.",pop:"303 pazienti, follow-up minimo 6 mesi; stratificati per terzili del rapporto di resezione in resezione a inclinazione mediale (<0,8), simmetrica (0,8-1,1) e a inclinazione laterale (>1,1).",results:"Spessore osseo residuo laterale maggiore del mediale in media (differenza 0,8mm; p<0,001); rapporto di resezione medio 0,9 (range 0,3-2,6). Inclinazione rotulea media 6,7° (range -11,2 a 25,7°); il rapporto di resezione è predittore indipendente dell'inclinazione (p<0,001), più alta nel gruppo a resezione mediale (7,6°±5,7° contro gli altri due gruppi; p=0,022). Le linee radiotrasparenti sono predette dall'angolo di inclinazione (OR 1,1; p=0,004), non dal rapporto di resezione in sé; tasso più alto nel gruppo a resezione mediale (5,2%) rispetto al laterale (3,9%) e al simmetrico (2,6%). Soglia di inclinazione a 7,8° predice le linee radiotrasparenti con sensibilità 90,9% e valore predittivo negativo 99,5%.",concl:"Gli autori concludono che una resezione rotulea a inclinazione mediale va evitata perché aumenta il rischio di inclinazione rotulea postoperatoria eccessiva, a sua volta associata a più linee radiotrasparenti attorno alla componente.",limits:"Studio retrospettivo su una sola piattaforma robotica (MAKO), non la VELYS che usi tu · variabili legate al paziente (BMI, comorbidità) non disponibili nel dataset retrospettivo e non inserite nei modelli multivariabili · follow-up minimo di soli 6 mesi, insufficiente per parlare di sopravvivenza della componente a lungo termine.",perte:"Non è la tua piattaforma robotica, ma il principio tecnico sul taglio rotuleo — evitare un'inclinazione mediale del piano di resezione per non spingere la rotula fuori asse — vale indipendentemente dal sistema usato, ed è un controllo intraoperatorio facilmente riproducibile."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Acta Orthopaedica",h:"La protesi parziale laterale si rivede più spesso della protesi totale",v:"Registro nazionale olandese, 847 protesi laterali contro 240.047 protesi totali: il rischio di revisione è più alto per la protesi laterale (hazard ratio corretto 2,15), confermato anche nel sottogruppo più recente (HR 1,55).",ax:"Koenraadt-van Oost, Van Boekel, Hoorntje, Kerkhoffs, Mulder, Van Steenbergen, Van Geenen",date:"set 2026",meta:"coorte di registro nazionale, Paesi Bassi, 847 protesi laterali contro 240.047 totali · [III/registro]",pmid:'42781970',doi:'10.2340/17453674.2026.46374',journal:"Acta Orthopaedica",authors:"Koenraadt-van Oost I, Van Boekel LC, Hoorntje A, Kerkhoffs GMMJ, Mulder PGH, Van Steenbergen LN, Van Geenen RCI",design:"Analisi del registro nazionale olandese delle artroplastiche (Dutch Arthroplasty Register, LROI), 2007-2021: confronto del rischio di revisione fra protesi di ginocchio compartimentale laterale e protesi totale, con pesi ATT (Average Treatment effect on the Treated) basati sul punteggio di propensione; sottoanalisi 2014-2021 con aggiustamento aggiuntivo per BMI e punteggio di Charnley; endpoint la revisione, censurata per decesso.",pop:"Coorte totale: 847 protesi laterali, 240.047 protesi totali. Sottogruppo 2014-2021: 560 protesi laterali, 155.621 protesi totali.",results:"Rischio di revisione più alto per la protesi laterale nella coorte totale (HR aggiustato per ATT 2,15; IC 95% 1,74-2,64; p<0,001) e nel sottogruppo più recente (HR aggiustato per ATT 1,55; IC 95% 1,08-2,21; p=0,02). Le stime pesate per ATT non differiscono sostanzialmente da quelle di una regressione di Cox multivariabile convenzionale.",concl:"Gli autori concludono che la protesi compartimentale laterale ha un rischio di revisione significativamente più alto della protesi totale, in un registro nazionale su oltre due decadi.",limits:"La protesi laterale è rara (847 casi in 15 anni, contro 240.047 totali): anche in un registro nazionale il numero di eventi resta limitato, e l'indicazione clinica alla protesi laterale — spesso casi più complessi o più giovani — può non essere completamente controllata dal solo aggiustamento per propensione · nessun dettaglio sul design implantare specifico né sulla tecnica (convenzionale o robotica) in nessuno dei due gruppi.",perte:"Riguarda il compartimento laterale, che non è la sede abituale della tua protesi monocompartimentale — la mediale è molto più frequente nella pratica corrente, inclusa la tua. Il segnale non si applica direttamente al gesto che fai di solito, ma è un argomento in più per selezionare con attenzione i rari casi di artrosi isolata del compartimento laterale, dove il registro suggerisce una sopravvivenza dell'impianto meno favorevole della protesi totale."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"The American Journal of Sports Medicine",h:"Un doppio fascio ricrea meglio la stabilità nativa del collaterale mediale",v:"Studio cadaverico su 27 ginocchia: la ricostruzione del collaterale mediale superficiale a doppio fascio, inlay/onlay retensionabile, restituisce una lassità più vicina al ginocchio nativo rispetto alla tecnica a singolo fascio, sia in valgo sia in extrarotazione.",ax:"Anz, Waller, Carroll, Colbrunn, Magoolaghan, Truett, Cohen, Kulkarni, Callanan",date:"set 2026",meta:"studio biomeccanico cadaverico, 27 ginocchia · [banco]",pmid:'42781775',doi:'10.1177/03635465261480465',journal:"The American Journal of Sports Medicine",authors:"Anz AW, Waller G, Carroll J, Colbrunn G, Magoolaghan AC, Truett J, Cohen A, Kulkarni M, Callanan MC",design:"Studio di laboratorio controllato su 27 ginocchia cadaveriche testate con un sistema robotico a 6 gradi di libertà, in stress in valgo e in extrarotazione: stato nativo, dopo sezione del legamento collaterale mediale superficiale (sMCL), poi dopo una di tre ricostruzioni con allograft di tibiale anteriore — inlay a singolo fascio, doppio fascio inlay/onlay con fissazione tibiale prossimale e distale, doppio fascio inlay/onlay con fissazione tibiale antero-posteriore distale; costrutti retensionabili, testati dopo cicli di flesso-estensione e successivo ritensionamento.",pop:"27 ginocchia cadaveriche; confronto fra stato nativo, stato leso e tre tecniche di ricostruzione con dispositivi a cappio regolabile.",results:"La sezione dell'sMCL aumenta in modo significativo la lassità in valgo e in extrarotazione rispetto allo stato nativo (p<0,001). Dopo ciclizzazione e ritensionamento, entrambe le ricostruzioni a doppio fascio ripristinano una stabilità significativamente maggiore della ricostruzione a singolo fascio ciclizzata (p<0,001), più vicine allo stato nativo sia in valgo (p<0,001) sia in extrarotazione (p<0,05). Per il valgo, nessuna differenza fra i costrutti a doppio fascio ritensionati e lo stato nativo (differenza media pooled 0,56°; IC 95% 0,05°-1,06°; p=0,032). Per l'extrarotazione, nessuna differenza fra il doppio fascio con fissazione antero-posteriore e lo stato nativo (p=0,836).",concl:"Gli autori concludono che una ricostruzione a doppio fascio, inlay/onlay, retensionabile, con impronta femorale più ampia e due punti di fissazione tibiale distale, restituisce una stabilità più vicina allo stato nativo rispetto alla tecnica a singolo fascio, e che la fissazione antero-posteriore ottiene il risultato più completo.",limits:"Studio cadaverico, nessun dato clinico né di paziente: la superiorità biomeccanica non implica automaticamente un esito clinico migliore · allograft di tibiale anteriore, non la tecnica con ancore FiberTak che usi tu · nessun dato sulla durata nel tempo del costrutto oltre la singola sessione di test.",perte:"La tua ricostruzione del collaterale mediale usa ancore FiberTak in tecnica onlay, non l'allograft a doppio fascio inlay/onlay testato qui: il costrutto non è il tuo, e il dato è di banco, non clinico. Il principio generale — che aumentare l'impronta di fissazione e i punti di ancoraggio distale avvicina di più alla lassità nativa — resta comunque un argomento tecnico da tenere presente."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"The American Journal of Sports Medicine",h:"L'età cambia quali biomarcatori sinoviali prevedono l'esito del LCA",v:"Coorte prospettica di 100 pazienti seguiti almeno 5 anni: l'età al momento della ricostruzione modula quali biomarcatori del liquido sinoviale preoperatorio predicono l'esito riferito dal paziente, con un'età maggiore associata a punteggi peggiori.",ax:"Ehlers, Kurtz, Montgomery, Kaplan, Strauss",date:"set 2026",meta:"coorte prospettica, 100 pazienti, follow-up minimo 5 anni · [III]",pmid:'42781773',doi:'10.1177/03635465261485707',journal:"The American Journal of Sports Medicine",authors:"Ehlers M, Kurtz JL, Montgomery SR, Kaplan DJ, Strauss EJ",design:"Studio di coorte prospettico su pazienti sottoposti a ricostruzione del LCA fra luglio 2011 e dicembre 2020: liquido sinoviale aspirato prima dell'incisione e analizzato per concentrazione di biomarcatori pro- e anti-infiammatori; esiti riferiti dal paziente (VAS dolore, Lysholm, Tegner, KOOS-PS) raccolti a un minimo di 5 anni; regressione multivariabile e analisi di processo condizionale per moderazione (durata dei sintomi) e mediazione (gravità della lesione condrale).",pop:"100 pazienti, età media 30,8±9,5 anni al momento dell'intervento, follow-up minimo 5 anni.",results:"Età più avanzata associata in modo indipendente a concentrazioni preoperatorie più basse di TIMP-1 (β=-0,0775; p=0,014), effetto moderato dalla durata dei sintomi (significativo sotto i 3,0 mesi e sopra gli 8,5 mesi). La gravità della lesione condrale non media l'associazione età-biomarcatori. Età più avanzata associata a esiti riferiti dal paziente peggiori a lungo termine e a minore probabilità di raggiungere la differenza minima clinicamente importante per dolore, funzione e attività. Concentrazioni più alte di MIP-1β associate a esiti funzionali peggiori, di MMP-3 a più dolore, di TIMP-2 a livelli di attività più bassi, di bFGF a funzione fisica migliore, con interazioni significative età-biomarcatore per TIMP-1, TIMP-2 e MIP-1β.",concl:"Gli autori concludono che l'età al momento della ricostruzione del LCA modifica il significato prognostico di alcuni biomarcatori del liquido sinoviale, ed è un fattore da incorporare nella stratificazione del rischio dopo la lesione.",limits:"100 pazienti in totale, suddivisi poi per fasce d'età e per singolo biomarcatore: i sottogruppi diventano piccoli e gli intervalli di confidenza dei singoli effetti non sono riportati nell'abstract · studio di associazione, non di meccanismo: non dimostra che i biomarcatori causino l'esito peggiore nei pazienti più anziani · popolazione monocentrica newyorkese, generalizzabilità non nota.",perte:"Non cambia la tua indicazione chirurgica, ma aggiunge un argomento biologico a una discussione che già fai con l'età del paziente: un LCA più anziano non è solo un LCA con più fattori di rischio meccanici, ha anche una risposta infiammatoria intra-articolare diversa che si associa a un recupero funzionale meno completo a 5-10 anni."},{n:7,mono:"m-gray",dot:"green",sec:"res",j:"Sports (Basel)",h:"Il rapporto innesto-impronta non predice il fallimento precoce del LCA",v:"Coorte retrospettiva singaporiana, 240 ricostruzioni con hamstring: il rapporto fra area dell'innesto e impronta tibiale nativa del LCA non è associato al fallimento a breve termine, su soli 7 eventi in tutta la coorte.",ax:"Teo, Lim, Tan, Lee, Wong, Han",date:"ago 2026",meta:"coorte retrospettiva monocentrica, 240 pazienti, Singapore · [III]",pmid:'42784363',doi:'10.3390/sports14090367',journal:"Sports (Basel)",authors:"Teo AQA, Lim ZY, Tan JHE, Lee JZJ, Wong HPN, Han F",design:"Studio di coorte retrospettivo su pazienti sottoposti a ricostruzione primaria del LCA con autoinnesto di hamstring in un centro terziario di Singapore in 3 anni: area dell'impronta tibiale nativa del LCA misurata su RM preoperatoria, area dell'innesto calcolata dal diametro del tunnel; fallimento diagnosticato clinicamente e confermato radiologicamente; analisi multivariabile su variabili prespecificate dalla letteratura.",pop:"240 pazienti, età media 24,4 anni.",results:"7 fallimenti dell'innesto in totale (2,92%), 2 dei quali sottoposti a revisione chirurgica. Nessuna associazione fra rapporto innesto-impronta e fallimento (71,9% contro 80,2%; p=0,386). Nessuna differenza nel tasso di fallimento fra innesti <8mm e ≥8mm (p>0,99). Il sesso, non il rapporto innesto-impronta, predice in modo significativo la dimensione dell'innesto.",concl:"Gli autori concludono che il rapporto fra area dell'innesto e impronta tibiale nativa non è associato al fallimento precoce, ma che il basso numero di eventi e il follow-up breve limitano conclusioni definitive.",limits:"Solo 7 eventi di fallimento in tutta la coorte: con numeri così piccoli lo studio non può escludere un'associazione clinicamente rilevante fra dimensionamento dell'innesto e fallimento, è uno studio muto più che uno studio negativo (vedi MUTE) · autoinnesto di hamstring, non il tendine quadricipitale/retto femorale che usi tu · follow-up a breve termine, gli stessi autori lo dichiarano.",perte:"Innesto diverso dal tuo (hamstring, non tendine quadricipitale/retto femorale) e la domanda — se la dimensione dell'innesto rispetto all'impronta nativa conti — non è quella su cui costruisci la tua indicazione. Utile soprattutto come promemoria metodologico: con soli 7 fallimenti su 240 pazienti, un risultato «non significativo» su un dimensionamento dell'innesto non equivale a una dimostrazione che le dimensioni non contino."}];
var SUGGQ=[{"k": "kol", "n": "Aaron J. Krych", "w": "Mayo Clinic, Rochester (Minnesota), Stati Uniti", "r": "Ultimo autore della scheda 1 di oggi (PICK) sul confronto fra fissazione con ancora intratunnel e riparazione transtibiale pull-through della radice meniscale: chirurgo di riferimento del Mayo Clinic per la chirurgia del menisco e della cartilagine. Corrispondenza tecnica diretta con la tua pratica — tu esegui la rifissazione della radice meniscale proprio con tecnica transtibiale pull-out, la stessa usata come comparatore in questo lavoro. Sostituisce la proposta di Alexandre Hardy (24 settembre, nessun segnale dell'utente arrivato per farlo ruotare)."}];
var BRIEF_TEXT="Oggi il filo conduttore è tecnico più che clinico: quando una tecnica consolidata viene messa a confronto con un'alternativa più recente, che cosa cambia davvero e che cosa resta solo apparenza per un follow-up più corto? Il lavoro del giorno arriva dal Mayo Clinic e riguarda esattamente la tua tecnica di riferimento per la radice meniscale, la riparazione transtibiale pull-through: confrontata con una fissazione più recente con ancora intratunnel su 150 ginocchia, i tassi di reintervento e di fallimento sono sovrapponibili, ma una quota più alta di pazienti operati con l'ancora raggiunge la soglia di soddisfazione soggettiva su dolore e funzione. Il dato onesto è nel follow-up: un anno e mezzo per il gruppo ancora, sei anni per il gruppo transtibiale — un confronto ancora indiretto, non un motivo per cambiare tecnica. Il resto della giornata segue lo stesso registro di dettaglio tecnico su aree della tua pratica: una placca mediale aggiuntiva che quasi azzera il ritardo di guarigione nell'osteotomia tibiale alta giapponese, l'orientamento del taglio rotuleo che nella protesi di ginocchio predice l'inclinazione postoperatoria e le linee radiotrasparenti, un registro olandese che segnala un rischio di revisione più alto per la rara protesi compartimentale laterale rispetto alla totale, un doppio fascio cadaverico che si avvicina di più alla stabilità nativa nella ricostruzione del collaterale mediale, e due studi sul legamento crociato anteriore — uno che lega l'età alla biologia infiammatoria del ginocchio e all'esito a lungo termine, l'altro che non trova, su troppo pochi eventi per dirlo con certezza, un legame fra le dimensioni dell'innesto e il suo fallimento precoce. Nessun richiamo di dispositivi, nessuna consensus nuova, nessuna tensione delle tue aperte toccata direttamente oggi.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi parto dalla tua tecnica per la radice meniscale, la transtibiale pull-through: il Mayo Clinic l'ha messa a confronto con un'alternativa più recente."}, {"chi": "B", "t": "E come è andata?"}, {"chi": "A", "t": "Su 150 ginocchia, i reinterventi sono praticamente uguali — 8% contro 14%, non significativo. Ma con la tecnica nuova, l'ancora intratunnel, un po' più di pazienti si dicono soddisfatti su dolore e funzione."}, {"chi": "B", "t": "Quindi la tua tecnica perde terreno?"}, {"chi": "A", "t": "Non proprio: il gruppo con l'ancora è stato seguito un anno e mezzo, quello con la transtibiale sei anni. Non è un confronto alla pari nel tempo."}, {"chi": "B", "t": "Quindi per la tua pratica: nessun motivo per cambiare, ma un dato da tenere d'occhio quando arriveranno follow-up più lunghi."}, {"chi": "A", "t": "Esatto. Il resto della giornata è nello stesso registro. In Giappone, aggiungere una piccola placca mediale nell'osteotomia tibiale alta riduce il ritardo di guarigione da un caso su cinque a uno su quaranta."}, {"chi": "B", "t": "Utile per chi fa osteotomie di slope come te."}, {"chi": "A", "t": "Un principio tecnico trasferibile, sì. E in Italia, uno studio su protesi robot-assistite mostra che un taglio della rotula troppo inclinato verso l'interno aumenta il rischio di segni radiografici di allentamento."}, {"chi": "B", "t": "Anche se non è la tua piattaforma robotica."}, {"chi": "A", "t": "Esatto, ma il controllo intraoperatorio è lo stesso, qualunque robot si usi. Poi un registro olandese: la protesi parziale sul lato esterno del ginocchio, quella laterale, si rivede più spesso della protesi totale."}, {"chi": "B", "t": "Riguarda anche la tua monocompartimentale?"}, {"chi": "A", "t": "No, quella è quasi sempre mediale nella pratica corrente — questo dato è specifico del compartimento laterale, più raro."}, {"chi": "B", "t": "E sul legamento crociato?"}, {"chi": "A", "t": "Due lavori: uno lega l'età del paziente alla biologia infiammatoria del ginocchio e a un recupero meno completo a 5-10 anni. L'altro, su un innesto diverso dal tuo, non trova un legame fra le dimensioni dell'innesto e il fallimento — ma con soli 7 eventi in 240 pazienti, è più uno studio muto che una prova."}, {"chi": "B", "t": "Giornata senza grandi scosse, quindi."}, {"chi": "A", "t": "Sì: nessun richiamo, nessuna consensus nuova, nessuna delle tue tensioni aperte toccata oggi. Solo dettaglio tecnico, in più aree della tua pratica."}];
